{"action":"write_file","path":"percentile.test.js","content":"'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { percentile } = require('./percentile');

test('median of an odd list', () => {
  assert.equal(percentile([5, 3, 1, 4, 2], 50), 3);
});

test('the ends', () => {
  assert.equal(percentile([4, 2, 9, 1], 0), 1);
  assert.equal(percentile([4, 2, 9, 1], 100), 9);
});

test('interpolation', () => {
  assert.equal(percentile([1, 2, 3, 4], 50), 2.5);
});

test('input array is not modified', () => {
  const arr = [4, 2, 9, 1];
  const copy = [...arr];
  percentile(arr, 50);
  assert.deepEqual(arr, copy);
});

test('validation errors', () => {
  assert.throws(() => percentile([], 50), RangeError);
  assert.throws(() => percentile('not an array', 50), RangeError);
  assert.throws(() => percentile([1, 2], -1), RangeError);
  assert.throws(() => percentile([1, 2], 101), RangeError);
  assert.throws(() => percentile([1, 2], NaN), RangeError);
  assert.throws(() => percentile([1, '2'], 50), TypeError);
  assert.throws(() => percentile([1, NaN], 50), TypeError);
  assert.throws(() => percentile([1, Infinity], 50), TypeError);
});
"}
